23	export type PlanType = "free" | "starter" | "growth" | "pro" | "agency";
24	
25	// ── Plan Helpers ────────────────────────────────────────────
26	
27	/** Any paid plan (starter and above) */
28	export function isPaidPlan(plan: PlanType): boolean {
29	  return plan !== "free";
30	}
31	
32	/** Growth plan and above (growth, pro, agency) */
33	export function isGrowthPlus(plan: PlanType): boolean {
34	  return plan === "growth" || plan === "pro" || plan === "agency";
35	}
36	
37	/** Pro plan and above (pro, agency) */
38	export function isProPlus(plan: PlanType): boolean {
39	  return plan === "pro" || plan === "agency";
40	}
41	
42	/** Agency plan only */
43	export function isAgencyPlan(plan: PlanType): boolean {
44	  return plan === "agency";
45	}
