import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { toast } from "sonner";
import supabase from "@/lib/supabase";
import { useAuth } from "@/contexts/AuthContext";
import type { CompetitorGroupWithUrls, CroPillar } from "@/types";
import type {
  CompetitorGroupRow,
  CompetitorUrlRow,
  CompetitorGroupInsert,
} from "@/types/database";

// ── Query keys ──────────────────────────────────────────────────

export const competitorKeys = {
  all: ["competitors"] as const,
  lists: () => [...competitorKeys.all, "list"] as const,
  list: (userId: string) => [...competitorKeys.lists(), userId] as const,
};

// ── Row mappers ─────────────────────────────────────────────────

function rowToGroup(
  row: CompetitorGroupRow & { competitor_urls: CompetitorUrlRow[] }
): CompetitorGroupWithUrls {
  return {
    id: row.id,
    user_id: row.user_id,
    name: row.name,
    primary_url: row.primary_url,
    created_at: row.created_at,
    competitor_urls: row.competitor_urls.map((u) => ({
      id: u.id,
      group_id: u.group_id,
      url: u.url,
      scan_id: u.scan_id,
      latest_score: u.latest_score,
      scanned_at: u.scanned_at,
    })),
  };
}

// ── Edge function response shape ───────────────────────────────

interface AnalyzeUrlResponse {
  overall_score?: number;
  scan_id?: string;
}

// ── useCompetitorGroups ─────────────────────────────────────────

export function useCompetitorGroups() {
  const { user } = useAuth();

  return useQuery({
    queryKey: competitorKeys.list(user?.id ?? ""),
    queryFn: async (): Promise<CompetitorGroupWithUrls[]> => {
      if (!user?.id) return [];

      const { data, error } = await supabase
        .from("competitor_groups")
        .select("*, competitor_urls(*)")
        .eq("user_id", user.id)
        .order("created_at", { ascending: false });

      if (error) throw new Error(error.message);

      return (
        data as Array<CompetitorGroupRow & { competitor_urls: CompetitorUrlRow[] }>
      ).map(rowToGroup);
    },
    enabled: !!user?.id,
    staleTime: 1000 * 30,
  });
}

// ── useCreateCompetitorGroup ────────────────────────────────────

interface CreateGroupInput {
  name: string;
  primary_url: string;
  competitor_urls: string[];
}

export function useCreateCompetitorGroup() {
  const { user } = useAuth();
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async (input: CreateGroupInput): Promise<CompetitorGroupWithUrls> => {
      if (!user?.id) throw new Error("Not authenticated");

      // 1. Create the group
      const groupInsert: CompetitorGroupInsert = {
        user_id: user.id,
        primary_url: input.primary_url,
        name: input.name,
      };

      const { data: groupData, error: groupError } = await supabase
        .from("competitor_groups")
        .insert(groupInsert)
        .select("*")
        .single();

      if (groupError) throw new Error(groupError.message);
      const group = groupData as CompetitorGroupRow;

      // 2. Insert all URLs (primary + competitors)
      const allUrls = [input.primary_url, ...input.competitor_urls];
      const urlRows = allUrls.map((url) => ({ group_id: group.id, url }));

      const { data: urlData, error: urlError } = await supabase
        .from("competitor_urls")
        .insert(urlRows)
        .select("*");

      if (urlError) throw new Error(urlError.message);

      return rowToGroup({
        ...group,
        competitor_urls: urlData as CompetitorUrlRow[],
      });
    },
    onSuccess: (data) => {
      if (!user?.id) return;
      queryClient.setQueryData<CompetitorGroupWithUrls[]>(
        competitorKeys.list(user.id),
        (prev) => (prev ? [data, ...prev] : [data])
      );
    },
    onError: (error: unknown) => {
      const msg = error instanceof Error ? error.message : "Failed to create competitor group";
      toast.error(msg);
    },
  });
}

// ── useDeleteCompetitorGroup ────────────────────────────────────

export function useDeleteCompetitorGroup() {
  const { user } = useAuth();
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async (groupId: string): Promise<void> => {
      if (!user?.id) throw new Error("Not authenticated");

      const { error } = await supabase
        .from("competitor_groups")
        .delete()
        .eq("id", groupId)
        .eq("user_id", user.id);

      if (error) throw new Error(error.message);
    },
    onSuccess: (_data, groupId) => {
      if (!user?.id) return;
      queryClient.setQueryData<CompetitorGroupWithUrls[]>(
        competitorKeys.list(user.id),
        (prev) => (prev ? prev.filter((g) => g.id !== groupId) : [])
      );
    },
    onError: (error: unknown) => {
      const msg = error instanceof Error ? error.message : "Failed to delete group";
      toast.error(msg);
    },
  });
}

// ── useScanCompetitor ───────────────────────────────────────────

interface ScanCompetitorInput {
  competitorUrlId: string;
  url: string;
  groupId: string;
}

export function useScanCompetitor() {
  const { user } = useAuth();
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async (input: ScanCompetitorInput): Promise<void> => {
      if (!user?.id) throw new Error("Not authenticated");

      // Invoke the same edge function used for regular scans
      const { data, error } = await supabase.functions.invoke("analyze-url", {
        body: { url: input.url, page_type: "landing" },
      });

      if (error) throw new Error(error.message);

      const result = data as AnalyzeUrlResponse;
      const overallScore = result?.overall_score ?? null;
      const scanId = result?.scan_id ?? null;

      // Update the competitor_urls row with scan_id + latest_score
      const { error: updateError } = await supabase
        .from("competitor_urls")
        .update({
          scan_id: scanId,
          latest_score: overallScore,
          scanned_at: new Date().toISOString(),
        })
        .eq("id", input.competitorUrlId);

      if (updateError) throw new Error(updateError.message);
    },
    onSuccess: (_data, input) => {
      if (!user?.id) return;
      // Refetch the group list to reflect updated scores
      void queryClient.invalidateQueries({
        queryKey: competitorKeys.list(user.id),
      });
      toast.success(`Scan complete for ${tryHostname(input.url)}`);
    },
    onError: (error: unknown) => {
      const msg = error instanceof Error ? error.message : "Scan failed";
      toast.error(msg);
    },
  });
}

// ── useScanAllCompetitors ───────────────────────────────────────

export function useScanAllCompetitors() {
  const scanCompetitor = useScanCompetitor();

  return useMutation({
    mutationFn: async (group: CompetitorGroupWithUrls): Promise<void> => {
      // Fire all URL scans in parallel — each updates its own row
      await Promise.allSettled(
        group.competitor_urls.map((cu) =>
          scanCompetitor.mutateAsync({
            competitorUrlId: cu.id,
            url: cu.url,
            groupId: group.id,
          })
        )
      );
    },
  });
}

// ── Pillar scores from a scan ───────────────────────────────────

interface ScanPillarScores {
  pillar_scores: Record<CroPillar, number> | null;
}

export function useCompetitorPillarScores(scanId: string | null) {
  return useQuery({
    queryKey: ["competitor-pillar-scores", scanId],
    queryFn: async (): Promise<Record<CroPillar, number> | null> => {
      if (!scanId) return null;

      const { data, error } = await supabase
        .from("scan_history")
        .select("pillar_scores")
        .eq("scan_id", scanId)
        .maybeSingle();

      if (error) throw new Error(error.message);
      return (data as ScanPillarScores | null)?.pillar_scores ?? null;
    },
    enabled: !!scanId,
    staleTime: 1000 * 60 * 5,
  });
}

// ── Helpers ─────────────────────────────────────────────────────

function tryHostname(url: string): string {
  try {
    return new URL(url).hostname.replace("www.", "");
  } catch {
    return url;
  }
}

import {
  Radar,
  RadarChart,
  PolarGrid,
  PolarAngleAxis,
  PolarRadiusAxis,
  Tooltip,
  Legend,
  ResponsiveContainer,
} from "recharts";
import type { CroPillar } from "@/types";
import { CRO_PILLARS } from "@/lib/constants";

// ── Chart colors — one per series ──────────────────────────────
const SERIES_COLORS = [
  "hsl(var(--primary))",
  "#f59e0b",
  "#10b981",
  "#ef4444",
  "#8b5cf6",
] as const;

// ── Types ───────────────────────────────────────────────────────

export interface RadarSeriesItem {
  name: string;
  scores: Partial<Record<CroPillar, number>>;
}

interface CompetitorRadarChartProps {
  data: RadarSeriesItem[];
}

// ── Recharts data shape ─────────────────────────────────────────

interface RadarDataPoint {
  pillar: string;
  fullMark: number;
  [key: string]: string | number;
}

function buildChartData(data: RadarSeriesItem[]): RadarDataPoint[] {
  return CRO_PILLARS.map((pillar) => {
    const point: RadarDataPoint = {
      pillar: pillar.label,
      fullMark: 100,
    };
    data.forEach((series) => {
      point[series.name] = series.scores[pillar.key] ?? 0;
    });
    return point;
  });
}

// ── Custom tooltip ───────────────────────────────────────────────

interface TooltipPayloadEntry {
  name: string;
  value: number;
  color: string;
}

interface CustomTooltipProps {
  active?: boolean;
  payload?: TooltipPayloadEntry[];
  label?: string;
}

function CustomTooltip({ active, payload, label }: CustomTooltipProps) {
  if (!active || !payload?.length) return null;

  return (
    <div className="rounded-lg border border-border/50 bg-popover px-3 py-2 shadow-md text-sm">
      <p className="mb-1.5 font-medium text-foreground">{label}</p>
      {payload.map((entry) => (
        <div key={entry.name} className="flex items-center gap-2">
          <span
            className="inline-block h-2 w-2 rounded-full shrink-0"
            style={{ background: entry.color }}
          />
          <span className="text-muted-foreground">{entry.name}:</span>
          <span className="font-medium tabular-nums text-foreground">{entry.value}</span>
        </div>
      ))}
    </div>
  );
}

// ── Component ────────────────────────────────────────────────────

export function CompetitorRadarChart({ data }: CompetitorRadarChartProps) {
  const chartData = buildChartData(data);

  return (
    <ResponsiveContainer width="100%" height={300}>
      <RadarChart data={chartData} margin={{ top: 10, right: 20, bottom: 10, left: 20 }}>
        <PolarGrid
          stroke="hsl(var(--border))"
          strokeOpacity={0.5}
        />
        <PolarAngleAxis
          dataKey="pillar"
          tick={{ fontSize: 11, fill: "hsl(var(--muted-foreground))" }}
          tickLine={false}
        />
        <PolarRadiusAxis
          angle={90}
          domain={[0, 100]}
          tick={{ fontSize: 10, fill: "hsl(var(--muted-foreground))" }}
          tickCount={5}
          stroke="hsl(var(--border))"
          strokeOpacity={0.3}
        />
        {data.map((series, index) => (
          <Radar
            key={series.name}
            name={series.name}
            dataKey={series.name}
            stroke={SERIES_COLORS[index % SERIES_COLORS.length]}
            fill={SERIES_COLORS[index % SERIES_COLORS.length]}
            fillOpacity={0.08}
            strokeWidth={2}
            dot={{ r: 3, fill: SERIES_COLORS[index % SERIES_COLORS.length] }}
          />
        ))}
        <Tooltip content={<CustomTooltip />} />
        <Legend
          wrapperStyle={{ fontSize: 12, paddingTop: 12 }}
          formatter={(value: string) => (
            <span style={{ color: "hsl(var(--muted-foreground))" }}>{value}</span>
          )}
        />
      </RadarChart>
    </ResponsiveContainer>
  );
}

import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { Badge } from "@/components/ui/badge";
import { cn } from "@/lib/utils";
import { CRO_PILLARS } from "@/lib/constants";
import type { CroPillar } from "@/types";

// ── Types ───────────────────────────────────────────────────────

export interface CompetitorScoreEntry {
  url: string;
  scores: Partial<Record<CroPillar, number>> | null;
  overallScore: number | null;
}

interface CompetitorScoreTableProps {
  primaryUrl: string;
  competitors: CompetitorScoreEntry[];
}

// ── Helpers ─────────────────────────────────────────────────────

function tryHostname(url: string): string {
  try {
    return new URL(url).hostname.replace("www.", "");
  } catch {
    return url;
  }
}

function scoreColor(score: number | null | undefined, isHighest: boolean, isLowest: boolean): string {
  if (score === null || score === undefined) return "text-muted-foreground";
  if (isHighest) return "text-emerald-600 font-semibold";
  if (isLowest) return "text-red-500 font-semibold";
  return "text-foreground";
}

function scoreBg(isHighest: boolean, isLowest: boolean): string {
  if (isHighest) return "bg-emerald-50/60";
  if (isLowest) return "bg-red-50/40";
  return "";
}

// ── Component ────────────────────────────────────────────────────

export function CompetitorScoreTable({ primaryUrl, competitors }: CompetitorScoreTableProps) {
  // All columns: primary first, then competitors
  const allEntries: CompetitorScoreEntry[] = competitors;

  return (
    <div className="overflow-x-auto scrollbar-thin rounded-lg border border-border/40">
      <Table>
        <TableHeader>
          <TableRow className="bg-muted/20 hover:bg-muted/20">
            <TableHead className="pl-4 min-w-[160px] font-semibold text-foreground">Pillar</TableHead>
            {/* Primary */}
            <TableHead className="text-center min-w-[120px]">
              <div className="flex flex-col items-center gap-0.5">
                <span className="text-xs text-muted-foreground">Your site</span>
                <span className="text-xs font-medium truncate max-w-[100px]" title={primaryUrl}>
                  {tryHostname(primaryUrl)}
                </span>
              </div>
            </TableHead>
            {/* Competitors (skip first entry which is primary) */}
            {allEntries.slice(1).map((entry) => (
              <TableHead key={entry.url} className="text-center min-w-[120px]">
                <div className="flex flex-col items-center gap-0.5">
                  <span className="text-xs text-muted-foreground">Competitor</span>
                  <span className="text-xs font-medium truncate max-w-[100px]" title={entry.url}>
                    {tryHostname(entry.url)}
                  </span>
                </div>
              </TableHead>
            ))}
          </TableRow>
        </TableHeader>
        <TableBody>
          {/* Per-pillar rows */}
          {CRO_PILLARS.map((pillar) => {
            const rowScores = allEntries.map((entry) =>
              entry.scores?.[pillar.key] ?? null
            );
            const validScores = rowScores.filter((s): s is number => s !== null);
            const maxScore = validScores.length ? Math.max(...validScores) : null;
            const minScore = validScores.length > 1 ? Math.min(...validScores) : null;

            return (
              <TableRow key={pillar.key} className="hover:bg-muted/10">
                <TableCell className="pl-4">
                  <div className="flex items-center gap-2">
                    <pillar.icon className="h-3.5 w-3.5 text-muted-foreground shrink-0" />
                    <span className="text-sm font-medium text-foreground">{pillar.label}</span>
                  </div>
                </TableCell>
                {rowScores.map((score, idx) => {
                  const isHighest = score !== null && score === maxScore;
                  const isLowest = score !== null && score === minScore && minScore !== maxScore;
                  return (
                    <TableCell
                      key={allEntries[idx]?.url ?? idx}
                      className={cn("text-center", scoreBg(isHighest, isLowest))}
                    >
                      {score !== null ? (
                        <div className="flex items-center justify-center gap-1.5">
                          <span className={cn("text-sm tabular-nums", scoreColor(score, isHighest, isLowest))}>
                            {score}
                          </span>
                          {isHighest && (
                            <Badge
                              variant="outline"
                              className="text-2xs border-emerald-200 bg-emerald-50 text-emerald-700 px-1 py-0 h-4"
                            >
                              Best
                            </Badge>
                          )}
                        </div>
                      ) : (
                        <span className="text-xs text-muted-foreground">--</span>
                      )}
                    </TableCell>
                  );
                })}
              </TableRow>
            );
          })}

          {/* Overall score row */}
          {(() => {
            const overallScores = allEntries.map((e) => e.overallScore);
            const validOverall = overallScores.filter((s): s is number => s !== null);
            const maxOverall = validOverall.length ? Math.max(...validOverall) : null;
            const minOverall = validOverall.length > 1 ? Math.min(...validOverall) : null;

            return (
              <TableRow className="bg-muted/10 font-medium border-t-2 border-border/50">
                <TableCell className="pl-4 font-semibold text-foreground">
                  Overall Score
                </TableCell>
                {overallScores.map((score, idx) => {
                  const isHighest = score !== null && score === maxOverall;
                  const isLowest = score !== null && score === minOverall && minOverall !== maxOverall;
                  return (
                    <TableCell
                      key={allEntries[idx]?.url ?? idx}
                      className={cn("text-center", scoreBg(isHighest, isLowest))}
                    >
                      {score !== null ? (
                        <div className="flex items-center justify-center gap-1.5">
                          <span className={cn("text-base font-bold tabular-nums", scoreColor(score, isHighest, isLowest))}>
                            {score}
                          </span>
                          {isHighest && (
                            <Badge
                              variant="outline"
                              className="text-2xs border-emerald-200 bg-emerald-50 text-emerald-700 px-1 py-0 h-4"
                            >
                              Winner
                            </Badge>
                          )}
                        </div>
                      ) : (
                        <span className="text-xs text-muted-foreground">--</span>
                      )}
                    </TableCell>
                  );
                })}
              </TableRow>
            );
          })()}
        </TableBody>
      </Table>
    </div>
  );
}

import { useState } from "react";
import { Plus, Trash2, Loader2, Swords } from "lucide-react";
import { toast } from "sonner";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { useCreateCompetitorGroup, useScanAllCompetitors } from "@/hooks/use-competitors";

// ── URL validation ───────────────────────────────────────────────

function normalizeUrl(raw: string): string {
  const trimmed = raw.trim();
  if (!trimmed) return trimmed;
  return /^https?:\/\//i.test(trimmed) ? trimmed : `https://${trimmed}`;
}

function isValidUrl(url: string): boolean {
  try {
    new URL(url);
    return true;
  } catch {
    return false;
  }
}

// ── Types ────────────────────────────────────────────────────────

interface CompetitorCreateFormProps {
  trigger?: React.ReactNode;
}

// ── Component ────────────────────────────────────────────────────

const MAX_COMPETITORS = 4;

export function CompetitorCreateForm({ trigger }: CompetitorCreateFormProps) {
  const [open, setOpen] = useState(false);
  const [groupName, setGroupName] = useState("My Competitors");
  const [primaryUrl, setPrimaryUrl] = useState("");
  const [competitorUrls, setCompetitorUrls] = useState<string[]>([""]);
  const [errors, setErrors] = useState<Record<string, string>>({});

  const createGroup = useCreateCompetitorGroup();
  const scanAll = useScanAllCompetitors();

  const isPending = createGroup.isPending || scanAll.isPending;

  function validate(): boolean {
    const nextErrors: Record<string, string> = {};

    if (!groupName.trim()) {
      nextErrors["name"] = "Group name is required";
    }

    const normalizedPrimary = normalizeUrl(primaryUrl);
    if (!normalizedPrimary || !isValidUrl(normalizedPrimary)) {
      nextErrors["primary"] = "Enter a valid URL (e.g. https://yoursite.com)";
    }

    competitorUrls.forEach((url, idx) => {
      if (!url.trim()) return; // empty slots are fine — skipped below
      const normalized = normalizeUrl(url);
      if (!isValidUrl(normalized)) {
        nextErrors[`competitor_${idx}`] = "Enter a valid URL";
      }
    });

    setErrors(nextErrors);
    return Object.keys(nextErrors).length === 0;
  }

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    if (!validate()) return;

    const normalizedPrimary = normalizeUrl(primaryUrl);
    const normalizedCompetitors = competitorUrls
      .map(normalizeUrl)
      .filter((url) => url && isValidUrl(url));

    if (normalizedCompetitors.length === 0) {
      toast.error("Add at least one competitor URL");
      return;
    }

    try {
      const group = await createGroup.mutateAsync({
        name: groupName.trim(),
        primary_url: normalizedPrimary,
        competitor_urls: normalizedCompetitors,
      });

      toast.success("Group created — starting scans...");

      // Fire-and-don't-await: scan all URLs in background
      // This is intentional — page loads immediately, scans update when done
      scanAll.mutate(group, {
        onSuccess: () => toast.success(`All scans complete for "${group.name}"`),
        onError: () => toast.error("Some scans failed — retry from the group card"),
      });

      setOpen(false);
      resetForm();
    } catch {
      // error toast handled by mutation
    }
  }

  function resetForm() {
    setGroupName("My Competitors");
    setPrimaryUrl("");
    setCompetitorUrls([""]);
    setErrors({});
  }

  function addCompetitor() {
    if (competitorUrls.length >= MAX_COMPETITORS) return;
    setCompetitorUrls((prev) => [...prev, ""]);
  }

  function removeCompetitor(index: number) {
    setCompetitorUrls((prev) => prev.filter((_, i) => i !== index));
    setErrors((prev) => {
      const next = { ...prev };
      delete next[`competitor_${index}`];
      return next;
    });
  }

  function updateCompetitor(index: number, value: string) {
    setCompetitorUrls((prev) => prev.map((u, i) => (i === index ? value : u)));
    if (errors[`competitor_${index}`]) {
      setErrors((prev) => {
        const next = { ...prev };
        delete next[`competitor_${index}`];
        return next;
      });
    }
  }

  return (
    <Dialog open={open} onOpenChange={(v) => { setOpen(v); if (!v) resetForm(); }}>
      <DialogTrigger asChild>
        {trigger ?? (
          <Button>
            <Swords className="mr-2 h-4 w-4" />
            New Comparison
          </Button>
        )}
      </DialogTrigger>

      <DialogContent className="sm:max-w-[520px]">
        <form onSubmit={(e) => void handleSubmit(e)}>
          <DialogHeader>
            <DialogTitle>Create Competitor Group</DialogTitle>
            <DialogDescription>
              Add your URL and up to 4 competitors. We'll scan all of them and generate a side-by-side CRO comparison.
            </DialogDescription>
          </DialogHeader>

          <div className="mt-5 space-y-5">
            {/* Group name */}
            <div className="space-y-1.5">
              <Label htmlFor="group-name">Group name</Label>
              <Input
                id="group-name"
                value={groupName}
                onChange={(e) => setGroupName(e.target.value)}
                placeholder="e.g. SaaS Competitors Q2"
                disabled={isPending}
              />
              {errors["name"] && (
                <p className="text-xs text-red-500">{errors["name"]}</p>
              )}
            </div>

            {/* Primary URL */}
            <div className="space-y-1.5">
              <Label htmlFor="primary-url">Your website URL</Label>
              <Input
                id="primary-url"
                type="url"
                value={primaryUrl}
                onChange={(e) => {
                  setPrimaryUrl(e.target.value);
                  if (errors["primary"]) setErrors((p) => { const n = { ...p }; delete n["primary"]; return n; });
                }}
                placeholder="https://yoursite.com"
                disabled={isPending}
              />
              {errors["primary"] && (
                <p className="text-xs text-red-500">{errors["primary"]}</p>
              )}
            </div>

            {/* Competitor URLs */}
            <div className="space-y-2">
              <Label>Competitor URLs</Label>
              {competitorUrls.map((url, idx) => (
                <div key={idx} className="flex items-center gap-2">
                  <Input
                    type="url"
                    value={url}
                    onChange={(e) => updateCompetitor(idx, e.target.value)}
                    placeholder={`https://competitor${idx + 1}.com`}
                    disabled={isPending}
                    className={errors[`competitor_${idx}`] ? "border-red-400" : ""}
                  />
                  {competitorUrls.length > 1 && (
                    <Button
                      type="button"
                      variant="ghost"
                      size="sm"
                      className="h-9 w-9 p-0 shrink-0 text-muted-foreground hover:text-red-500"
                      onClick={() => removeCompetitor(idx)}
                      disabled={isPending}
                      aria-label={`Remove competitor ${idx + 1}`}
                    >
                      <Trash2 className="h-4 w-4" />
                    </Button>
                  )}
                </div>
              ))}
              {competitorUrls.map((_, idx) =>
                errors[`competitor_${idx}`] ? (
                  <p key={idx} className="text-xs text-red-500">
                    Competitor {idx + 1}: {errors[`competitor_${idx}`]}
                  </p>
                ) : null
              )}
              {competitorUrls.length < MAX_COMPETITORS && (
                <Button
                  type="button"
                  variant="outline"
                  size="sm"
                  onClick={addCompetitor}
                  disabled={isPending}
                  className="mt-1"
                >
                  <Plus className="mr-1.5 h-3.5 w-3.5" />
                  Add another
                </Button>
              )}
            </div>
          </div>

          <DialogFooter className="mt-6">
            <Button
              type="button"
              variant="outline"
              onClick={() => setOpen(false)}
              disabled={isPending}
            >
              Cancel
            </Button>
            <Button type="submit" disabled={isPending}>
              {isPending ? (
                <>
                  <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                  Creating...
                </>
              ) : (
                <>
                  <Swords className="mr-2 h-4 w-4" />
                  Create & Scan All
                </>
              )}
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  );
}

import { useState } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { Swords, ChevronDown, RefreshCw, Trash2, Loader2 } from "lucide-react";
import { toast } from "sonner";
import { Card, CardContent, CardHeader } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Skeleton } from "@/components/ui/skeleton";
import { Separator } from "@/components/ui/separator";
import { PageHeader } from "@/components/shared/PageHeader";
import { PageTransition } from "@/components/shared/PageTransition";
import { EmptyState } from "@/components/shared/EmptyState";
import { ErrorState } from "@/components/shared/ErrorState";
import { PremiumLock } from "@/components/shared/PremiumLock";
import { ScoreRing } from "@/components/shared/ScoreRing";
import { CompetitorCreateForm } from "@/components/competitors/CompetitorCreateForm";
import { CompetitorRadarChart } from "@/components/competitors/CompetitorRadarChart";
import { CompetitorScoreTable } from "@/components/competitors/CompetitorScoreTable";
import {
  useCompetitorGroups,
  useDeleteCompetitorGroup,
  useScanAllCompetitors,
} from "@/hooks/use-competitors";
import { useAuth } from "@/contexts/AuthContext";
import { isGrowthPlus } from "@/types";
import { CRO_PILLARS } from "@/lib/constants";
import type { CompetitorGroupWithUrls, CroPillar } from "@/types";
import type { RadarSeriesItem } from "@/components/competitors/CompetitorRadarChart";
import type { CompetitorScoreEntry } from "@/components/competitors/CompetitorScoreTable";
import { cn } from "@/lib/utils";

// ── Helpers ─────────────────────────────────────────────────────

function tryHostname(url: string): string {
  try {
    return new URL(url).hostname.replace("www.", "");
  } catch {
    return url;
  }
}

function formatDate(dateStr: string | null): string {
  if (!dateStr) return "Not scanned";
  return new Date(dateStr).toLocaleDateString("en-US", {
    month: "short",
    day: "numeric",
  });
}

// ── Build radar + table data from a group ───────────────────────

function buildRadarData(group: CompetitorGroupWithUrls): RadarSeriesItem[] {
  return group.competitor_urls.map((cu) => {
    const scores: Partial<Record<CroPillar, number>> = {};
    // We don't have pillar scores in competitor_urls — only overall.
    // The radar shows overall-score-only placeholder until pillar data is available.
    // For now, distribute overall score as equal across all pillars if no pillar data.
    const fallback = cu.latest_score ?? 0;
    CRO_PILLARS.forEach((p) => {
      scores[p.key] = fallback;
    });
    return { name: tryHostname(cu.url), scores };
  });
}

function buildTableData(group: CompetitorGroupWithUrls): CompetitorScoreEntry[] {
  return group.competitor_urls.map((cu) => ({
    url: cu.url,
    scores: null, // pillar scores require scan_results join — not in this table
    overallScore: cu.latest_score,
  }));
}

// ── Loading skeleton ─────────────────────────────────────────────

function CompetitorGroupSkeleton() {
  return (
    <Card className="border-border/40 shadow-soft">
      <CardHeader className="pb-3">
        <div className="flex items-center justify-between">
          <div className="space-y-1.5">
            <Skeleton className="h-5 w-40" />
            <Skeleton className="h-4 w-28" />
          </div>
          <div className="flex gap-2">
            <Skeleton className="h-8 w-20 rounded-lg" />
            <Skeleton className="h-8 w-8 rounded-lg" />
          </div>
        </div>
      </CardHeader>
      <CardContent>
        <div className="grid grid-cols-2 gap-3 sm:grid-cols-3 md:grid-cols-5">
          {[1, 2, 3].map((i) => (
            <div key={i} className="rounded-lg border border-border/30 p-3 space-y-2">
              <Skeleton className="h-4 w-20" />
              <Skeleton className="h-8 w-8 rounded-full mx-auto" />
              <Skeleton className="h-3 w-16 mx-auto" />
            </div>
          ))}
        </div>
      </CardContent>
    </Card>
  );
}

// ── Group card ───────────────────────────────────────────────────

interface GroupCardProps {
  group: CompetitorGroupWithUrls;
}

function GroupCard({ group }: GroupCardProps) {
  const [expanded, setExpanded] = useState(false);
  const deleteGroup = useDeleteCompetitorGroup();
  const scanAll = useScanAllCompetitors();

  const isScanning = scanAll.isPending;
  const isDeleting = deleteGroup.isPending;

  function handleScanAll() {
    scanAll.mutate(group, {
      onSuccess: () => toast.success(`All scans complete for "${group.name}"`),
    });
  }

  function handleDelete() {
    deleteGroup.mutate(group.id, {
      onSuccess: () => toast.success(`"${group.name}" deleted`),
    });
  }

  const radarData = buildRadarData(group);
  const tableData = buildTableData(group);

  return (
    <motion.div
      initial={{ opacity: 0, y: 12 }}
      animate={{ opacity: 1, y: 0 }}
      exit={{ opacity: 0, y: -6 }}
      transition={{ duration: 0.25, ease: "easeOut" }}
    >
      <Card className="border-border/40 shadow-soft overflow-hidden">
        <CardHeader className="pb-3">
          <div className="flex flex-col gap-3 sm:flex-row sm:items-start sm:justify-between">
            <div>
              <h3 className="font-semibold text-base text-foreground">{group.name}</h3>
              <p className="text-sm text-muted-foreground mt-0.5">
                {group.competitor_urls.length} URLs &middot; Created {formatDate(group.created_at)}
              </p>
            </div>
            <div className="flex items-center gap-2 shrink-0">
              <Button
                variant="outline"
                size="sm"
                onClick={handleScanAll}
                disabled={isScanning || isDeleting}
              >
                {isScanning ? (
                  <><Loader2 className="mr-1.5 h-3.5 w-3.5 animate-spin" />Scanning...</>
                ) : (
                  <><RefreshCw className="mr-1.5 h-3.5 w-3.5" />Scan All</>
                )}
              </Button>
              <Button
                variant="ghost"
                size="sm"
                className="h-8 w-8 p-0 text-muted-foreground hover:text-red-500"
                onClick={handleDelete}
                disabled={isDeleting || isScanning}
                aria-label="Delete group"
              >
                {isDeleting ? (
                  <Loader2 className="h-4 w-4 animate-spin" />
                ) : (
                  <Trash2 className="h-4 w-4" />
                )}
              </Button>
            </div>
          </div>
        </CardHeader>

        {/* URL score cards */}
        <CardContent className="pt-0">
          <div className="grid grid-cols-2 gap-3 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5">
            {group.competitor_urls.map((cu, idx) => {
              const isPrimary = cu.url === group.primary_url;
              return (
                <div
                  key={cu.id}
                  className={cn(
                    "relative flex flex-col items-center gap-2 rounded-xl border p-3 transition-colors",
                    isPrimary
                      ? "border-primary/30 bg-primary/5"
                      : "border-border/40 bg-muted/20"
                  )}
                >
                  {isPrimary && (
                    <Badge
                      variant="outline"
                      className="absolute -top-2 left-1/2 -translate-x-1/2 text-2xs border-primary/30 bg-background text-primary px-1.5 py-0"
                    >
                      You
                    </Badge>
                  )}
                  {idx > 0 && !isPrimary && (
                    <Badge
                      variant="outline"
                      className="absolute -top-2 left-1/2 -translate-x-1/2 text-2xs border-border/50 bg-background text-muted-foreground px-1.5 py-0"
                    >
                      #{idx}
                    </Badge>
                  )}
                  <p className="text-xs font-medium text-foreground truncate w-full text-center" title={cu.url}>
                    {tryHostname(cu.url)}
                  </p>
                  {cu.latest_score !== null ? (
                    <ScoreRing score={cu.latest_score} size={48} strokeWidth={4} showLabel={false} />
                  ) : (
                    <div className="flex h-12 w-12 items-center justify-center rounded-full border-2 border-dashed border-border/50">
                      <span className="text-xs text-muted-foreground">--</span>
                    </div>
                  )}
                  <span className="text-xs text-muted-foreground">{formatDate(cu.scanned_at)}</span>
                </div>
              );
            })}
          </div>

          {/* Expand / collapse */}
          <Separator className="my-4" />
          <button
            type="button"
            onClick={() => setExpanded((v) => !v)}
            className="flex w-full items-center justify-between text-sm font-medium text-muted-foreground hover:text-foreground transition-colors"
          >
            <span>Detailed Comparison</span>
            <ChevronDown
              className={cn("h-4 w-4 transition-transform duration-200", expanded && "rotate-180")}
            />
          </button>

          <AnimatePresence>
            {expanded && (
              <motion.div
                initial={{ opacity: 0, height: 0 }}
                animate={{ opacity: 1, height: "auto" }}
                exit={{ opacity: 0, height: 0 }}
                transition={{ duration: 0.25, ease: "easeInOut" }}
                className="overflow-hidden"
              >
                <div className="pt-4 space-y-6">
                  {/* Radar chart */}
                  <div>
                    <h4 className="mb-3 text-sm font-semibold text-foreground">Score Radar</h4>
                    <CompetitorRadarChart data={radarData} />
                  </div>
                  {/* Score table */}
                  <div>
                    <h4 className="mb-3 text-sm font-semibold text-foreground">Pillar Breakdown</h4>
                    <CompetitorScoreTable
                      primaryUrl={group.primary_url}
                      competitors={tableData}
                    />
                  </div>
                </div>
              </motion.div>
            )}
          </AnimatePresence>
        </CardContent>
      </Card>
    </motion.div>
  );
}

// ── PremiumLock preview content ──────────────────────────────────

function LockedPreview() {
  return (
    <div className="pointer-events-none select-none space-y-4">
      {[1, 2].map((i) => (
        <Card key={i} className="border-border/40">
          <CardHeader className="pb-3">
            <div className="flex items-center justify-between">
              <div className="space-y-1">
                <Skeleton className="h-5 w-36 bg-muted/60" />
                <Skeleton className="h-4 w-24 bg-muted/40" />
              </div>
              <Skeleton className="h-8 w-24 rounded-lg bg-muted/60" />
            </div>
          </CardHeader>
          <CardContent>
            <div className="grid grid-cols-3 gap-3">
              {[1, 2, 3].map((j) => (
                <Skeleton key={j} className="h-20 rounded-xl bg-muted/40" />
              ))}
            </div>
          </CardContent>
        </Card>
      ))}
    </div>
  );
}

// ── Page ─────────────────────────────────────────────────────────

const Competitors = () => {
  const { profile } = useAuth();
  const canAccess = profile ? isGrowthPlus(profile.plan) : false;

  const { data: groups = [], isLoading, isError, refetch } = useCompetitorGroups();

  if (!canAccess) {
    return (
      <PageTransition>
        <div className="space-y-6">
          <PageHeader
            title="Competitor Benchmarking"
            description="Compare your CRO scores against competitors across all 7 pillars."
          />
          <PremiumLock message="Upgrade to Growth or higher to unlock competitor benchmarking">
            <LockedPreview />
          </PremiumLock>
        </div>
      </PageTransition>
    );
  }

  return (
    <PageTransition>
      <div className="space-y-6">
        <PageHeader
          title="Competitor Benchmarking"
          description="Compare your CRO scores against competitors across all 7 pillars."
        >
          <CompetitorCreateForm />
        </PageHeader>

        {isLoading ? (
          <div className="space-y-4">
            <CompetitorGroupSkeleton />
            <CompetitorGroupSkeleton />
          </div>
        ) : isError ? (
          <ErrorState
            title="Failed to load competitor groups"
            description="There was a problem fetching your competitor groups. Check your connection and try again."
            onRetry={() => void refetch()}
          />
        ) : groups.length === 0 ? (
          <EmptyState
            icon={Swords}
            title="No comparisons yet"
            description="Create your first competitor group to see how you stack up across all 7 CRO pillars."
            actionLabel="Add First Competitor Group"
            onAction={() => {
              /* CompetitorCreateForm in header handles open; trigger re-render here is not needed */
            }}
          />
        ) : (
          <AnimatePresence initial={false}>
            <div className="space-y-4">
              {groups.map((group) => (
                <GroupCard key={group.id} group={group} />
              ))}
            </div>
          </AnimatePresence>
        )}
      </div>
    </PageTransition>
  );
};

export default Competitors;

